const estructura = $input.first().json;
const parsear = $('🔍 Parsear Versiones Inglés').item.json;
const wpItem = $('🖼️ Obtener URL de Imagen').first().json;
const presentacionId = $('📋 Slides: Copiar Template').item.json.id;

const slideId = estructura.slides?.[0]?.objectId || 'p1';
const pageElements = estructura.slides?.[0]?.pageElements || [];

const wpImageUrl = wpItem?.imagen_url || null;
const titulo = parsear.texto_canva_titulo_en || parsear.texto_canva_titulo || 'Post Title';

// TEXT requests
const textRequests = [
  { replaceAllText: { containsText: { text: '[titulo_post]', matchCase: true }, replaceText: titulo } },
  { replaceAllText: { containsText: { text: '[descripcion_post]', matchCase: true }, replaceText: parsear.texto_canva_subtitulo_en || parsear.texto_canva_subtitulo || 'Post description' } }
];

const titleShape = pageElements.find(el =>
  (el.shape?.text?.textElements || []).some(te => (te.textRun?.content || '').includes('[titulo_post]'))
);
if (titleShape) {
  let fontSize = 52;
  if (titulo.length > 15) fontSize = 40;
  if (titulo.length > 22) fontSize = 32;
  if (titulo.length > 30) fontSize = 26;
  textRequests.push({
    updateTextStyle: {
      objectId: titleShape.objectId,
      textRange: { type: 'ALL' },
      style: { fontSize: { magnitude: fontSize, unit: 'PT' } },
      fields: 'fontSize'
    }
  });
}

// IMAGE: use replaceImage on the existing image element in the template
let imageRequest = null;
if (wpImageUrl) {
  const imageElement = pageElements.find(el => el.image !== undefined);
  if (imageElement) {
    imageRequest = {
      requests: [{
        replaceImage: {
          imageObjectId: imageElement.objectId,
          url: wpImageUrl,
          imageReplaceMethod: 'CENTER_CROP'
        }
      }]
    };
  }
}

return [{ json: { presentacionId, textRequests, imageRequest, wpImageUrl, titulo, subtitulo: parsear.texto_canva_subtitulo } }];

